    27	type TaggedClientError =
    28		| ApiError
    29		| NetworkError
    30		| NotFoundError
    31		| RateLimitError
    32		| ValidationError;
    33	
    34	function isTaggedClientError(
    35		error: Error | string,
    36	): error is TaggedClientError {
    37		return (
    38			error instanceof ApiError ||
    39			error instanceof NetworkError ||
    40			error instanceof NotFoundError ||
    41			error instanceof RateLimitError ||
    42			error instanceof ValidationError
    43		);
    44	}
    45	
    46	function executionFields(
    47		error: Error | string,
    48	): Omit<CliDiagnostic, "code" | "message"> {
    49		if (!isHevyHttpError(error) && !isTaggedClientError(error)) return {};
    50		const {
    51			code: _code,
    52			status: _status,
    53			...execution
    54		} = createExecutionErrorProjection(error);
    55		return execution;
    56	}
    57	
    58	export function diagnostic(error: Error | string): CliDiagnostic {
    59		if (error instanceof ConfigurationError)
    60			return { code: EXIT.configuration, message: error.message };
    61		if (error instanceof ApiResponseError)
    62			return {
    63				code: EXIT.api,
    64				message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
    65				...executionFields(error),
    66			};
    67		if (
    68			error instanceof HevyHttpError ||
    69			isHevyHttpError(error) ||
    70			isTaggedClientError(error)
    71		) {
    72			const status = "status" in error ? error.status : undefined;
    73			if (status === 401)
    74				return {
    75					code: EXIT.api,
    76					message: "Authentication failed; check HEVY_API_KEY",
    77					...executionFields(error),
    78				};
    79			if (status !== undefined)
    80				return {
    81					code: EXIT.api,
    82					message: `Hevy API request failed (HTTP ${status})`,
    83					...executionFields(error),
    84				};
    85			return {
    86				code: EXIT.network,
    87				message:
    88					("code" in error ? error.code : undefined) === "ETIMEDOUT"
    89						? "Hevy API request timed out"
    90						: "Unable to reach the Hevy API",
    91				...executionFields(error),
    92			};
    93		}
    94		if (error instanceof UsageError)
    95			return {
    96				code: EXIT.usage,
    97				message: error.message.replace(/https?:\/\/\S+/gi, "[redacted]"),
    98			};
    99		return { code: EXIT.usage, message: "Command failed" };
